Definition g8l3f_exit (ra sp gp tp t1 s0 s1 s9 s10 s11 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (DR dn : Z) : machine_state -> Prop :=
  fun ms' => exists (t0' t2' t3' t4' s2' s3' s4' s5' s6' s7' s8' a0' a1' a2' a3' a4' a5' a6' a7' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1 t2' s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2' s3' s4' s5' s6' s7' s8' s9 s10 s11 t3' t4' t5 t6)
             F (Z_to_bv 64 0x139b84) fc None m' (seg_rom asegs)
    /\ munch [(DR, DR + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.
Lemma g8l3_fullc : forall (ra gp tp t0 t2 t3 t4 s0 s3 s4 s5 s6 s7 s8 s9 s10 s11 a0 a1 a2 a3 a4 a5 a6 a7 t5 w88 w96 : word)
    F fc (m : mem)
    (FP dh swpl dwpl SY hangh PS3 PD3 SR sn DR dn fl sh rsh dy dpixh sy spixh : Z),
  1 <= dh <= 20000 -> - 2^16 <= dy <= 2^16 -> 0 < dpixh <= 20000 -> - 2^16 <= sy <= 2^16 -> 0 < spixh <= 20000 ->
  0 <= SY -> SY + dh <= spixh -> - 2^20 <= hangh <= 2^20 ->
  spixh - SY + Z.min (sy + dpixh - dy + Z.min hangh 0 - spixh) 0 = dh ->
  0 < swpl <= 2^24 -> 0 < dwpl <= 2^24 -> swpl * dh <= 2^24 -> dwpl * dh <= 2^24 ->
  0 < SR -> SR mod 4 = 0 -> SR + sn <= 2^47 -> 0 < DR -> DR mod 4 = 0 -> DR + dn <= 2^47 -> PS3 mod 4 = 0 -> PD3 mod 4 = 0 ->
  (DR + dn <= 0x7fff7000 \/ 0x10007fff8000 <= DR) ->
  0 < FP -> FP mod 16 = 0 -> FP + 256 <= 2^47 -> (DR + dn <= FP \/ FP + 256 <= DR) ->
  0 <= fl < 2 -> 0 <= sh < 32 -> 0 <= rsh < 32 ->
  (forall i', 0 <= i' <= dh -> SR <= PS3 + 4 * (swpl * i') /\ PS3 + 4 * (swpl * i') + 4 <= SR + sn + 4 * swpl) ->
  (fl = 0 -> forall i', 0 <= i' < dh -> PS3 + 4 * (swpl * i') + 8 <= SR + sn) ->
  (forall i', 0 <= i' < dh -> SR <= PS3 + 4 * (swpl * i') /\ PS3 + 4 * (swpl * i') + 4 <= SR + sn) ->
  (forall i', 0 <= i' < dh -> DR <= PD3 + 4 * (dwpl * i') /\ PD3 + 4 * (dwpl * i') + 4 <= DR + dn) ->
  rw_cells asegs m (FP + 8) [C8 (Z_to_bv 64 fl)] -> rw_cells asegs m (FP + 24) [C8 (Z_to_bv 64 0)] ->
  rw_cells asegs m (FP + 40) [C8 (Z_to_bv 64 hangh); C8 (Z_to_bv 64 SY); C8 (Z_to_bv 64 sy); C8 (Z_to_bv 64 dpixh); C8 (Z_to_bv 64 dy);
                              C8 (Z_to_bv 64 spixh); C8 w88; C8 w96; C8 (Z_to_bv 64 PS3)] ->
  rw_cells asegs m (FP + 120) [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 swpl); C8 (Z_to_bv 64 dwpl)] ->
  wr_at asegs m SR sn -> acc asegs m SR sn -> wr_at asegs m DR dn -> acc asegs m DR dn -> mem_inv asegs m ->
  evt asegs (g8l3f_exit ra (Z_to_bv 64 FP) gp tp (Z_to_bv 64 2147450880) s0 (Z_to_bv 64 rsh) s9 s10 s11 t5 (Z_to_bv 64 sh) F fc m DR dn)
    (MS (mkR ra (Z_to_bv 64 FP) gp tp t0 (Z_to_bv 64 2147450880) t2 s0 (Z_to_bv 64 rsh) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 PD3) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 (Z_to_bv 64 sh))
